CREATE TABLE [dbo].[RepIVRDetail](	  [date] DATETIME NOT NULL	, [telephone] VARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [user] VARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [disposition] VARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [callid] INT NOT NULL	, [options] VARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [statusTime] INT NOT NULL	, [year] INT NOT NULL	, [month] INT NOT NULL	, [day] INT NOT NULL	, [hour] INT NOT NULL	, [minutes] INT NOT NULL	, [dnis] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('')	, [ivrName] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NULL)CREATE NONCLUSTERED INDEX [IX_RepIVRDetail] ON [dbo].[RepIVRDetail] ([date] ASC)